 1  import { useState } from 'react';
 2  import {
 3    Badge,
 4    Button,
 5    List,
 6    ListItem,
 7    ListItemIcon,
 8    ListItemText,
 9    Paper,
10    Typography,
11  } from '@mui/material';
12  import { visuallyHidden } from '@mui/utils';
13  import NotificationsIcon from '@mui/icons-material/Notifications';
14  import MailIcon from '@mui/icons-material/Mail';
15  
16  export interface Notice {
17    id: number;
18    text: string;
19    read: boolean;
20  }
21  
22  const NOTICES: Notice[] = [
23    { id: 1, text: 'Alan Turing joined your workspace', read: false },
24    { id: 2, text: 'Your export is ready', read: false },
25    { id: 3, text: 'Weekly digest sent', read: true },
26    { id: 4, text: 'Grace Hopper changed her role', read: false },
27  ];
28  
29  export function Notifications({ initial = NOTICES }: { initial?: Notice[] }) {
30    const [notices, setNotices] = useState(initial);
31    const unread = notices.filter((n) => !n.read).length;
32  
33    return (
34      <Paper component="section" aria-labelledby="notifications-title">
35        <Typography id="notifications-title" variant="h6" component="h1">
36          <Badge badgeContent={unread} color="secondary">
37            <NotificationsIcon aria-hidden />
38          </Badge>{' '}
39          Notifications
40          <Typography variant="srOnly" component="span">
41            {unread === 0 ? 'No unread notifications' : `${unread} unread notifications`}
42          </Typography>
43        </Typography>
44        <List dense>
45          {notices.map((n) => (
46            <ListItem key={n.id} selected={!n.read}>
47              <ListItemIcon>
48                <MailIcon color={n.read ? 'disabled' : 'primary'} />
49              </ListItemIcon>
50              <ListItemText primary={n.text} secondary={n.read ? 'Read' : 'Unread'} />
51            </ListItem>
52          ))}
53        </List>
54        <Button
55          disabled={unread === 0}
56          onClick={() => setNotices(notices.map((n) => ({ ...n, read: true })))}
57        >
58          Mark all as read
59        </Button>
60      </Paper>
61    );
62  }
